/**
 * Texture mapping data of the pack converter (src/editions/convert/*.json, generated by
 * scripts/gen-convert-maps.ts): file format, path hygiene, well-known pairs and renames, and, against the
 * real game files (TO_FIXTURES: Java client jars), that every Java path exists in its release and that
 * the rename steps carry every 1.12.2 texture to a 26.3 path (or say it was removed).
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { unzipSync } from 'fflate';
import { loadJavaBedrockMap, loadJavaRenames, type JavaBedrockMap, type JavaRenames } from '../../src/editions/convert/maps';
import { KNOWN_RELEASES } from '../../src/editions/java/packformats';
import { bedrockTexturesFromFiles, catalogFromIndex, type BedrockIndexFile } from '../../src/editions/bedrock/catalog';
import { javaJarPath } from '../tools/models/fixtures';

const ROOT = new URL('../../', import.meta.url).pathname;
const NO_JAR = (v: string) => `Minecraft ${v} jar not found (set TO_FIXTURES to a folder with research-cache/jars/${v}.jar)`;

let mapP: Promise<JavaBedrockMap> | null = null;
let renamesP: Promise<JavaRenames> | null = null;
const map = () => (mapP ??= loadJavaBedrockMap());
const renames = () => (renamesP ??= loadJavaRenames());

/** Texture paths (relative to assets/minecraft/textures/, no extension) of a client jar. */
function jarTextures(version: string): Set<string> | null {
  const jar = javaJarPath(version);
  if (!jar) return null;
  const out = new Set<string>();
  unzipSync(new Uint8Array(readFileSync(jar)), {
    filter: (f) => {
      if (f.name.startsWith('assets/minecraft/textures/') && f.name.endsWith('.png')) out.add(f.name.slice('assets/minecraft/textures/'.length, -4));
      return false;
    },
  });
  return out;
}

const cleanPath = (p: string) => typeof p === 'string' && p.length > 0 && !p.startsWith('/') && !p.endsWith('/') && !/\.(png|tga|jpe?g)$/i.test(p) && !p.includes('//') && !p.includes('\\');

/** Applies every rename step after `from` (exclusive) up to `to` (inclusive) to a path. */
function follow(r: JavaRenames, path: string, from: string, to: string): { paths: string[]; removedIn?: string } {
  const lo = KNOWN_RELEASES.indexOf(from);
  const hi = KNOWN_RELEASES.indexOf(to);
  let paths = [path];
  for (const step of r.steps) {
    const i = KNOWN_RELEASES.indexOf(step.version);
    if (i <= lo || i > hi) continue;
    const next: string[] = [];
    for (const p of paths) {
      const n = step.renames[p];
      if (n !== undefined) next.push(...(Array.isArray(n) ? n : [n]));
      else if (step.removed?.includes(p)) return { paths: [], removedIn: step.version };
      else next.push(p);
    }
    paths = [...new Set(next)];
  }
  return { paths };
}

test('java-bedrock map: format, versions and clean paths', async () => {
  const m = await map();
  assert.equal(m.format, 1);
  assert.match(m.java, /^\d+\.\d+(\.\d+)?$/);
  assert.match(m.bedrock, /^\d+\.\d+\.\d+\.\d+$/);
  assert.ok(m.pairs.length > 2000, `only ${m.pairs.length} pairs`);
  for (const list of [m.pairs, m.layoutDiffers ?? []])
    for (const pair of list) {
      assert.ok(Array.isArray(pair) && pair.length === 2, `bad pair ${JSON.stringify(pair)}`);
      assert.ok(cleanPath(pair[0]) && cleanPath(pair[1]), `bad path in ${JSON.stringify(pair)}`);
    }
});

test('java-bedrock map: no duplicate pairs, and nothing both paired and reported as a layout change', async () => {
  const m = await map();
  const seen = new Set<string>();
  for (const [j, b] of m.pairs) {
    const k = `${j}|${b}`;
    assert.ok(!seen.has(k), `duplicate pair ${k}`);
    seen.add(k);
  }
  const lay = new Set<string>();
  for (const [j, b] of m.layoutDiffers ?? []) {
    const k = `${j}|${b}`;
    assert.ok(!seen.has(k), `${k} is both a pair and a layout change`);
    assert.ok(!lay.has(k), `duplicate layout entry ${k}`);
    lay.add(k);
  }
});

test('java-bedrock map: well-known pairs', async () => {
  const m = await map();
  const has = (j: string, b: string) => m.pairs.some(([x, y]) => x === j && y === b);
  const expected: [string, string][] = [
    ['block/stone', 'blocks/stone'],
    ['block/grass_block_top', 'blocks/grass_top'],
    ['block/oak_planks', 'blocks/planks_oak'],
    ['block/oak_log', 'blocks/log_oak'],
    ['block/dirt', 'blocks/dirt'],
    ['block/cobblestone', 'blocks/cobblestone'],
    ['block/white_wool', 'blocks/wool_colored_white'],
    ['block/oak_leaves', 'blocks/leaves_oak'],
    ['block/water_still', 'blocks/water_still_grey'],
    ['item/diamond_sword', 'items/diamond_sword'],
    ['item/apple', 'items/apple'],
    ['item/golden_apple', 'items/apple_golden'],
    ['environment/celestial/sun', 'environment/sun'],
    ['environment/clouds', 'environment/clouds'],
    ['entity/creeper/creeper', 'entity/creeper/creeper'],
    ['painting/backyard', 'painting/backyard'],
    ['map/map_background', 'map/map_background'],
    ['misc/pumpkinblur', 'misc/pumpkinblur'],
  ];
  for (const [j, b] of expected) assert.ok(has(j, b), `missing pair ${j} <-> ${b}`);
  // Different layouts are reported, never paired
  assert.ok(!has('entity/chest/normal', 'entity/chest/normal'));
  assert.ok((m.layoutDiffers ?? []).some(([j, b]) => j === 'entity/chest/normal' && b === 'entity/chest/normal'));
  assert.ok(!m.pairs.some(([j, b]) => j === 'block/grass_block_side_overlay' && b === 'blocks/grass_side'), 'Bedrock grass_side keeps its tint mask in alpha');
  // Blank images never pair unrelated textures
  assert.ok(!m.pairs.some(([j]) => j === 'block/redstone_dust_overlay' || j === 'gui/tab_header_background'));
});

test('java-bedrock map: every Bedrock path is in the bundled catalogue of that release', async () => {
  const m = await map();
  const index = JSON.parse(readFileSync(`${ROOT}public/data/bedrock/index-main.json`, 'utf8')) as BedrockIndexFile;
  assert.equal(index.version, m.bedrock, 'the map was generated for the Bedrock release the app bundles');
  const ids = new Set(bedrockTexturesFromFiles(catalogFromIndex(index).files).map((t) => t.id));
  const missing = [...m.pairs, ...(m.layoutDiffers ?? [])].map(([, b]) => b).filter((b) => !ids.has(b));
  assert.deepEqual([...new Set(missing)], []);
});

test('java-bedrock map: every Java path exists in that release', { skip: javaJarPath('26.3') ? false : NO_JAR('26.3') }, async () => {
  const m = await map();
  const java = jarTextures(m.java)!;
  const missing = [...m.pairs, ...(m.layoutDiffers ?? [])].map(([j]) => j).filter((j) => !java.has(j));
  assert.deepEqual([...new Set(missing)], []);
});

test('java renames: format, release order and clean paths', async () => {
  const r = await renames();
  assert.equal(r.format, 1);
  let last = -1;
  for (const step of r.steps) {
    const i = KNOWN_RELEASES.indexOf(step.version);
    assert.ok(i >= 0, `${step.version} is not a known release`);
    assert.ok(i > last, `${step.version} is out of order`);
    last = i;
    for (const [from, to] of Object.entries(step.renames)) {
      assert.ok(cleanPath(from), `${step.version}: bad path ${from}`);
      const list = Array.isArray(to) ? to : [to];
      assert.ok(list.length > 0 && list.every(cleanPath), `${step.version}: bad target for ${from}`);
      assert.ok(!list.includes(from), `${step.version}: ${from} renamed to itself`);
    }
    for (const p of step.removed ?? []) {
      assert.ok(cleanPath(p));
      assert.ok(!(p in step.renames), `${step.version}: ${p} both renamed and removed`);
    }
  }
});

test('java renames: well-known renames', async () => {
  const r = await renames();
  const at = (v: string) => r.steps.find((s) => s.version === v)?.renames ?? {};
  const flat = at('1.13');
  const expected: Record<string, string> = {
    'blocks/stone_granite': 'block/granite',
    'blocks/stone': 'block/stone',
    'blocks/grass_top': 'block/grass_block_top',
    'blocks/grass_side': 'block/grass_block_side',
    'blocks/log_oak': 'block/oak_log',
    'blocks/planks_oak': 'block/oak_planks',
    'blocks/wool_colored_white': 'block/white_wool',
    'blocks/hardened_clay': 'block/terracotta',
    'blocks/web': 'block/cobweb',
    'items/apple': 'item/apple',
    'items/diamond_sword': 'item/diamond_sword',
    'items/gold_ingot': 'item/gold_ingot',
    'items/dye_powder_black': 'item/ink_sac',
    'items/record_cat': 'item/music_disc_cat',
  };
  for (const [from, to] of Object.entries(expected)) assert.equal(flat[from], to, `1.13: ${from}`);
  assert.equal(at('1.14')['item/sign'], 'item/oak_sign');
  assert.equal(at('1.17')['block/grass_path_top'], 'block/dirt_path_top');
  assert.equal(at('1.20.3')['block/grass'], 'block/short_grass');
  assert.equal(at('1.21.2')['models/armor/diamond_layer_1'], 'entity/equipment/humanoid/diamond');
  assert.equal(at('1.21.9')['block/chain'], 'block/iron_chain');
  assert.equal(at('1.21.11')['environment/sun'], 'environment/celestial/sun');
});

test('java renames: chains compose (tallgrass -> grass -> short_grass)', async () => {
  const r = await renames();
  assert.deepEqual(follow(r, 'blocks/tallgrass', '1.12.2', '26.3').paths, ['block/short_grass']);
  assert.deepEqual(follow(r, 'blocks/grass_top', '1.12.2', '26.3').paths, ['block/grass_block_top']);
  assert.deepEqual(follow(r, 'models/armor/diamond_layer_1', '1.12.2', '26.3').paths, ['entity/equipment/humanoid/diamond']);
});

const BOTH = javaJarPath('1.12.2') && javaJarPath('26.3');
test('java renames: every 1.12.2 texture reaches a 26.3 path or is listed as removed', { skip: BOTH ? false : NO_JAR('1.12.2 and 26.3') }, async () => {
  const r = await renames();
  const old = jarTextures('1.12.2')!;
  const now = jarTextures('26.3')!;
  const lost: string[] = [];
  let reached = 0;
  let removed = 0;
  for (const p of old) {
    const res = follow(r, p, '1.12.2', '26.3');
    if (res.removedIn) removed++;
    else if (res.paths.every((q) => now.has(q))) reached++;
    else lost.push(`${p} -> ${res.paths.join(',')}`);
  }
  assert.deepEqual(lost, []);
  // Fonts (unicode pages, 1.20) and GUI sheets (cut into sprites, 1.20.2) are mostly gone; the rest lives on.
  const art = [...old].filter((p) => !/^(font|gui)\//.test(p));
  const artReached = art.filter((p) => !follow(r, p, '1.12.2', '26.3').removedIn).length;
  assert.ok(artReached > art.length * 0.9, `only ${artReached} of ${art.length} non-GUI textures reach 26.3 (${reached} reached, ${removed} removed overall)`);
});

test('java renames: each step matches its jars (keys gone, targets new)', { skip: javaJarPath('1.12.2') && javaJarPath('1.13') ? false : NO_JAR('1.12.2 and 1.13') }, async () => {
  const r = await renames();
  const step = r.steps.find((s) => s.version === '1.13')!;
  const before = jarTextures('1.12.2')!;
  const after = jarTextures('1.13')!;
  for (const [from, to] of Object.entries(step.renames)) {
    assert.ok(before.has(from) && !after.has(from), `${from} should exist in 1.12.2 only`);
    for (const t of Array.isArray(to) ? to : [to]) assert.ok(after.has(t), `${t} should exist in 1.13`);
  }
  for (const p of step.removed ?? []) assert.ok(before.has(p) && !after.has(p));
});
